package com.asmj.marketplace.controller;

import com.asmj.marketplace.audit.AuditService;
import com.asmj.marketplace.model.UserAccount;
import com.asmj.marketplace.repository.UserAccountRepository;
import com.asmj.marketplace.rewards.*;
import java.math.BigDecimal;import java.security.Principal;import java.time.*;import java.util.*;
import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;import org.springframework.web.servlet.mvc.support.RedirectAttributes;

@Controller
public class SellerRewardsController {
 private final SellerRewardProgramRepository programs;private final SellerRewardAwardRepository awards;private final SellerRewardService service;private final UserAccountRepository users;private final AuditService audit;
 public SellerRewardsController(SellerRewardProgramRepository programs,SellerRewardAwardRepository awards,SellerRewardService service,UserAccountRepository users,AuditService audit){this.programs=programs;this.awards=awards;this.service=service;this.users=users;this.audit=audit;}
 private SellerRewardProgram program(){return programs.findById("seller-rewards").orElseGet(()->{SellerRewardProgram p=new SellerRewardProgram();LocalDate end=LocalDate.now(ZoneId.of("Asia/Kolkata"));p.setPeriodEnd(end);p.setPeriodStart(end.minusMonths(6).plusDays(1));return p;});}
 @GetMapping("/admin/seller-rewards") public String admin(Model model){SellerRewardProgram p=program();model.addAttribute("program",p);model.addAttribute("ranking",service.ranking(p));model.addAttribute("awards",awards.findByPeriodStartAndPeriodEndOrderByRankAsc(p.getPeriodStart(),p.getPeriodEnd()));model.addAttribute("awardHistory",awards.findAllByOrderByPeriodEndDescRankAsc());return "admin/seller-rewards";}
 @PostMapping("/admin/seller-rewards/save") public String save(@RequestParam LocalDate periodStart,@RequestParam LocalDate periodEnd,@RequestParam int minimumCompletedOrders,@RequestParam String rewardTitle1,@RequestParam String rewardTitle2,@RequestParam String rewardTitle3,@RequestParam String rewardTitle4,@RequestParam String rewardTitle5,@RequestParam BigDecimal rewardAmount1,@RequestParam BigDecimal rewardAmount2,@RequestParam BigDecimal rewardAmount3,@RequestParam BigDecimal rewardAmount4,@RequestParam BigDecimal rewardAmount5,Principal principal,RedirectAttributes ra){
  try{SellerRewardProgram existing=program();if(existing.isPublished()&&Objects.equals(existing.getPeriodStart(),periodStart)&&Objects.equals(existing.getPeriodEnd(),periodEnd))throw new IllegalArgumentException("This period has published winners. Create the next six-month period to configure new rewards.");if(periodStart==null||periodEnd==null||!periodEnd.equals(periodStart.plusMonths(6).minusDays(1)))throw new IllegalArgumentException("Choose an exact six-month period: end date must be six months after the start date minus one day.");if(minimumCompletedOrders<1||minimumCompletedOrders>100000)throw new IllegalArgumentException("Minimum completed orders must be between 1 and 100000.");String[] titles={rewardTitle1,rewardTitle2,rewardTitle3,rewardTitle4,rewardTitle5};BigDecimal[] amounts={rewardAmount1,rewardAmount2,rewardAmount3,rewardAmount4,rewardAmount5};for(int i=0;i<5;i++){if(titles[i]==null||titles[i].isBlank()||titles[i].length()>80)throw new IllegalArgumentException("Enter a reward title for all five ranks (maximum 80 characters).");if(amounts[i]==null||amounts[i].signum()<0||amounts[i].compareTo(new BigDecimal("10000000"))>0)throw new IllegalArgumentException("Reward amounts must be between ₹0 and ₹1 crore.");}
   SellerRewardProgram p=program();boolean changed=!Objects.equals(p.getPeriodStart(),periodStart)||!Objects.equals(p.getPeriodEnd(),periodEnd);p.setPeriodStart(periodStart);p.setPeriodEnd(periodEnd);p.setMinimumCompletedOrders(minimumCompletedOrders);p.setRewardTitles(titles);p.setRewardAmounts(amounts);if(changed){p.setPublished(false);p.setPublishedAt(null);}programs.save(p);audit.record(principal.getName(),"ADMIN","SELLER_REWARD_PROGRAM_SAVED","SELLER_REWARDS",p.getId(),"Period "+periodStart+" to "+periodEnd);ra.addFlashAttribute("successMessage","Seller reward programme saved. Review the provisional ranking before publishing winners.");
  }catch(IllegalArgumentException ex){ra.addFlashAttribute("errorMessage",ex.getMessage());}return "redirect:/admin/seller-rewards";
 }
 @PostMapping("/admin/seller-rewards/publish") public String publish(Principal principal,RedirectAttributes ra){try{SellerRewardProgram p=program();if(p.getPeriodStart()==null||p.getPeriodEnd()==null||!p.getPeriodEnd().equals(p.getPeriodStart().plusMonths(6).minusDays(1)))throw new IllegalArgumentException("Save a valid six-month reward period first.");if(p.getPeriodEnd().isAfter(LocalDate.now(ZoneId.of("Asia/Kolkata"))))throw new IllegalArgumentException("Winners can only be published after the six-month period has ended.");List<SellerRankingRow> ranked=service.ranking(p).stream().filter(r->r.rank()>0).toList();if(ranked.isEmpty())throw new IllegalArgumentException("No eligible vendors currently meet the minimum order requirement and commission eligibility rules.");awards.deleteByPeriodStartAndPeriodEnd(p.getPeriodStart(),p.getPeriodEnd());Instant now=Instant.now();for(SellerRankingRow r:ranked){int i=r.rank()-1;SellerRewardAward a=new SellerRewardAward();a.setVendorUserId(r.vendorUserId());a.setVendorName(r.vendorName());a.setPeriodStart(p.getPeriodStart());a.setPeriodEnd(p.getPeriodEnd());a.setRank(r.rank());a.setCompletedOrders(r.completedOrders());a.setSalesValue(r.salesValue());a.setAverageRating(r.averageRating());a.setCancellationRate(r.cancellationRate());a.setRewardTitle(p.getRewardTitles()[i]);a.setRewardAmount(p.getRewardAmounts()[i]);a.setPublishedAt(now);awards.save(a);}p.setPublished(true);p.setPublishedAt(now);programs.save(p);audit.record(principal.getName(),"ADMIN","SELLER_REWARD_WINNERS_PUBLISHED","SELLER_REWARDS",p.getId(),"Published "+ranked.size()+" winners for "+p.getPeriodStart()+" to "+p.getPeriodEnd());ra.addFlashAttribute("successMessage","Seller reward winners published. Vendors can now see their awards.");}catch(IllegalArgumentException ex){ra.addFlashAttribute("errorMessage",ex.getMessage());}return "redirect:/admin/seller-rewards";}
 @GetMapping("/vendor/rewards") public String vendor(Principal principal,Model model){UserAccount u=users.findByEmailIgnoreCase(principal.getName()).orElseThrow();SellerRewardProgram p=program();List<SellerRankingRow> ranking=service.ranking(p);model.addAttribute("program",p);model.addAttribute("ranking",ranking);model.addAttribute("myRanking",ranking.stream().filter(r->r.vendorUserId().equals(u.getId())).findFirst().orElse(null));model.addAttribute("myAwards",awards.findByVendorUserIdOrderByPeriodEndDescRankAsc(u.getId()));model.addAttribute("publishedAwards",p.isPublished()?awards.findByPeriodStartAndPeriodEndOrderByRankAsc(p.getPeriodStart(),p.getPeriodEnd()):List.of());return "vendor/rewards";}
}
